select ac_cargar_unidad($ac${"slug":"consumo-1","rama":"consumo","orden":1,"nivel":1,"titulo_es":"Lo que hay detrás de lo que comprás","bajada_es":"Cada cosa que comprás tiene una historia antes de llegar a tus manos y otra después. Cómo leerla, y por qué la mejor compra a veces es la que no se hace.","objetivos_es":["Describir las etapas del ciclo de vida de un producto","Interpretar la huella ecológica y el día del sobregiro de la Tierra","Explicar los impactos de la moda rápida","Reconocer que en muchos aparatos la mayor huella está en la fabricación","Aplicar criterios para comprar menos y mejor, como el costo por uso"],"repasa":["tronco-3","tronco-1"],"requiere_tronco":1,"fuentes":["global-footprint","emf-textiles","unep-moda","ewaste-monitor","ellen-macarthur"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-1.s1","orden":1,"tipo":"leccion","titulo_es":"La vida de un producto","bajada_es":"Extracción, fabricación, transporte, uso y descarte: las cinco etapas de todo lo que compramos.","minutos":9,"pasos":[{"slug":"consumo-1.s1.p1","orden":1,"grupo":"consumo-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De la mina al tacho","cuerpo":["Todo producto tiene un ciclo de vida: se extraen materias primas (minerales, petróleo, madera, algodón), se fabrican materiales y piezas, se arma el producto, se transporta y se vende, se usa durante un tiempo y, al final, se descarta, se recicla o se reutiliza.","En cada etapa se usan energía, agua y materiales, y se generan emisiones y residuos. El análisis de ciclo de vida, que viste en la rama de Alimentación, suma todo eso."]},"solucion":{}},{"slug":"consumo-1.s1.p2","orden":2,"grupo":"consumo-1.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del ciclo de vida de una remera de algodón.","items":[{"id":"i1","texto":"Se cultiva el algodón"},{"id":"i2","texto":"Se hila y se teje la tela"},{"id":"i3","texto":"Se tiñe y se cose la remera"},{"id":"i4","texto":"Se transporta y se vende"},{"id":"i5","texto":"Se usa y se lava muchas veces"},{"id":"i6","texto":"Se descarta o se reutiliza"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Seis etapas. En cada una se puede reducir el impacto."}},{"slug":"consumo-1.s1.p3","orden":3,"grupo":"consumo-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dónde está el impacto","cuerpo":["No todos los productos tienen el impacto en el mismo lugar. En un celular, la mayor parte de la huella está en la fabricación. En una heladera o un auto a nafta, en el uso, porque consumen energía durante años. En la comida, en la producción en el campo. En muchas prendas, en la fabricación de la tela y en los lavados.","Saber dónde está el impacto de cada producto dice dónde conviene actuar: comprar menos y hacerlo durar, o usarlo con eficiencia."]},"solucion":{}},{"slug":"consumo-1.s1.p4","orden":4,"grupo":"consumo-1.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Dónde está la mayor parte del impacto de cada producto?","grupos":[{"id":"g1","nombre":"En la fabricación"},{"id":"g2","nombre":"En el uso"}],"items":[{"id":"i1","texto":"Celular"},{"id":"i2","texto":"Heladera"},{"id":"i3","texto":"Notebook"},{"id":"i4","texto":"Auto a nafta"},{"id":"i5","texto":"Muebles de madera"},{"id":"i6","texto":"Aire acondicionado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Para los primeros, la clave es hacerlos durar. Para los segundos, elegir eficientes y usarlos bien."}},{"slug":"consumo-1.s1.p5","orden":5,"grupo":"consumo-1.s1.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un celular, la mayor parte de la huella de carbono está en la fabricación. ¿Qué conviene para reducirla?","opciones":[{"id":"o1","texto":"Usarlo más años antes de cambiarlo"},{"id":"o2","texto":"Cargarlo menos veces por semana"},{"id":"o3","texto":"Bajar el brillo de la pantalla"},{"id":"o4","texto":"Comprar uno nuevo cada año, más eficiente"}]},"solucion":{"clave":["o1"],"explicacion":"Si la huella está en la fabricación, cada año más de uso reparte ese impacto y evita fabricar otro.","por_opcion":{"o3":"Ahorra un poco de energía, pero el uso es una parte chica de su huella."}}},{"slug":"consumo-1.s1.p6","orden":6,"grupo":"consumo-1.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué usar un celular cuatro años en vez de dos reduce su huella anual.","items":[{"id":"i1","texto":"La fabricación concentra la mayor parte de la huella"},{"id":"i2","texto":"Esa huella se reparte entre los años de uso"},{"id":"i3","texto":"Con cuatro años, cada año carga con la mitad que con dos"},{"id":"i4","texto":"Además, se evita fabricar un celular nuevo"},{"id":"i5","texto":"Usarlo más años aumenta la huella de su fabricación"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Alargar la vida útil es la palanca más grande para los productos cuya huella está en la fabricación."}},{"slug":"consumo-1.s1.p7","orden":7,"grupo":"consumo-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 60 kg de CO₂e. ¿Cuántos kg por año \"le toca\" a cada año de uso si se usa 4 años en vez de 2? (Dividí la fabricación por los años)","unidad":"kg CO₂e por año","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"60 ÷ 4 = 15 kg por año, contra 30 si se usara 2 años."}},{"slug":"consumo-1.s1.p7.v2","orden":7,"grupo":"consumo-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 80 kg de CO₂e. ¿Cuántos kg por año \"le toca\" a cada año de uso si se usa 5 años en vez de 2? (Dividí la fabricación por los años)","unidad":"kg CO₂e por año","decimales":1},"solucion":{"valor":16,"tolerancia":0.32,"explicacion":"80 ÷ 5 = 16 kg por año, contra 40 si se usara 2 años."}},{"slug":"consumo-1.s1.p7.v3","orden":7,"grupo":"consumo-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 50 kg de CO₂e. ¿Cuántos kg por año \"le toca\" a cada año de uso si se usa 6 años en vez de 3? (Dividí la fabricación por los años)","unidad":"kg CO₂e por año","decimales":1},"solucion":{"valor":8.333333333333334,"tolerancia":0.16666666666666669,"explicacion":"50 ÷ 6 = 8,333 kg por año, contra 16,667 si se usara 3 años."}},{"slug":"consumo-1.s1.p8","orden":8,"grupo":"consumo-1.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Todos los productos tienen la mayor parte de su impacto en el transporte.","razones":[{"id":"r1","texto":"Porque en muchos productos pesa más la fabricación o el uso"},{"id":"r2","texto":"Porque los productos no se transportan"},{"id":"r3","texto":"Porque el transporte no tiene ningún impacto"}]},"solucion":{"valor":false,"explicacion":"Depende del producto: en muchos está en la fabricación o en el uso. El transporte suele ser una parte chica, salvo excepciones como el transporte aéreo.","clave":["r1"]}},{"slug":"consumo-1.s1.p9","orden":9,"grupo":"consumo-1.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa del ciclo de vida con un impacto típico.","izquierda":[{"id":"a1","texto":"Extracción"},{"id":"a2","texto":"Fabricación"},{"id":"a3","texto":"Uso"},{"id":"a4","texto":"Descarte"}],"derecha":[{"id":"b1","texto":"Minas, desmontes y uso de agua"},{"id":"b2","texto":"Energía de fábricas y químicos"},{"id":"b3","texto":"Energía y agua mientras se usa"},{"id":"b4","texto":"Residuos en rellenos o basurales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada etapa tiene sus impactos. Mirar solo una puede engañar."}},{"slug":"consumo-1.s1.p10","orden":10,"grupo":"consumo-1.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones reducen el impacto de un producto a lo largo de su ciclo de vida? Marcá todas.","opciones":[{"id":"o1","texto":"Elegir uno que dure más"},{"id":"o2","texto":"Repararlo cuando se rompe"},{"id":"o3","texto":"Usarlo con eficiencia"},{"id":"o4","texto":"Darle una segunda vida cuando ya no lo necesitás"},{"id":"o5","texto":"Cambiarlo apenas sale un modelo nuevo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Durar, reparar, usar bien y pasar a otro: cuatro formas de estirar el ciclo de vida."}},{"slug":"consumo-1.s1.p11","orden":11,"grupo":"consumo-1.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Nuestro celular dura años con actualizaciones."},{"id":"s2","texto":"Cambiá tu celular cada año: el modelo nuevo es más eficiente y ayuda al planeta."},{"id":"s3","texto":"Tiene repuestos disponibles."},{"id":"s4","texto":"Como consume poca batería, su impacto ambiental es casi nulo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber dónde está el impacto desarma muchas publicidades.","por_opcion":{"s2":"La mayor parte de la huella está en fabricar el nuevo: cambiarlo seguido aumenta el impacto.","s4":"La fabricación concentra la mayor parte de su huella, no el uso."}}},{"slug":"consumo-1.s1.p12","orden":12,"grupo":"consumo-1.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Todo producto tiene un {{0}} de vida; en un celular la mayor parte de la huella está en la {{1}} y en una heladera, en el {{2}}.","banco":[{"id":"w1","texto":"ciclo"},{"id":"w2","texto":"fabricación"},{"id":"w3","texto":"uso"},{"id":"w4","texto":"precio"},{"id":"w5","texto":"venta"},{"id":"w6","texto":"envase"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para leer cualquier producto."}}]},{"slug":"consumo-1.s2","orden":2,"tipo":"leccion","titulo_es":"La huella ecológica","bajada_es":"Cuántos planetas harían falta si todos viviéramos igual, y qué es el día del sobregiro de la Tierra.","minutos":11,"pasos":[{"slug":"consumo-1.s2.p1","orden":1,"grupo":"consumo-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una cuenta de superficie","cuerpo":["La huella ecológica mide cuánta superficie de tierra y mar productiva hace falta para producir lo que consume una persona, un país o toda la humanidad, y para absorber sus emisiones de CO₂. Se compara con la biocapacidad: lo que la naturaleza puede regenerar en un año.","Según la Global Footprint Network, la humanidad usa hoy los recursos que regenerarían alrededor de 1,7 planetas Tierra. Como tenemos uno solo, estamos gastando el \"capital\" natural: talando más de lo que crece, pescando más de lo que se repone y acumulando CO₂."],"destacado":{"valor":"≈ 1,7","texto":"planetas Tierra haría falta para regenerar lo que la humanidad usa hoy, según la Global Footprint Network."}},"solucion":{}},{"slug":"consumo-1.s2.p2","orden":2,"grupo":"consumo-1.s2.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que la humanidad usa \"1,7 planetas\"?","opciones":[{"id":"o1","texto":"Que usamos más de lo que la Tierra regenera por año"},{"id":"o2","texto":"Que existen 1,7 planetas habitables disponibles"},{"id":"o3","texto":"Que la población mundial se multiplicó por 1,7"},{"id":"o4","texto":"Que la Tierra creció un 70 % en tamaño"}]},"solucion":{"clave":["o1"],"explicacion":"Es como gastar más de lo que se cobra: se va comiendo el ahorro.","por_opcion":{"o3":"No es población: es consumo comparado con lo que la naturaleza regenera."}}},{"slug":"consumo-1.s2.p3","orden":3,"grupo":"consumo-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El día del sobregiro","cuerpo":["El día del sobregiro de la Tierra marca la fecha del año en la que la humanidad ya usó todo lo que la naturaleza puede regenerar en ese año. En los últimos años cayó a fines de julio o principios de agosto: desde ahí hasta diciembre, vivimos \"a crédito\".","Cada país tiene su propia fecha, según su consumo. Los países con mayor consumo por persona agotan su parte mucho antes."]},"solucion":{}},{"slug":"consumo-1.s2.p4","orden":4,"grupo":"consumo-1.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad usa 1,7 planetas, ¿en qué día del año (del 1 al 365) se agotaría lo que la Tierra regenera? Dividí 365 por 1,7 y redondeá al entero.","unidad":"día del año","decimales":0},"solucion":{"valor":215,"tolerancia":1,"explicacion":"365 ÷ 1,7 ≈ 215. Cae a fines de julio o principios de agosto."}},{"slug":"consumo-1.s2.p4.v2","orden":4,"grupo":"consumo-1.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad usa 2 planetas, ¿en qué día del año (del 1 al 365) se agotaría lo que la Tierra regenera? Dividí 365 por 2 y redondeá al entero.","unidad":"día del año","decimales":0},"solucion":{"valor":183,"tolerancia":1,"explicacion":"365 ÷ 2 ≈ 183. Cuanto más planetas usamos, más temprano llega el sobregiro."}},{"slug":"consumo-1.s2.p4.v3","orden":4,"grupo":"consumo-1.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad usa 1,5 planetas, ¿en qué día del año (del 1 al 365) se agotaría lo que la Tierra regenera? Dividí 365 por 1,5 y redondeá al entero.","unidad":"día del año","decimales":0},"solucion":{"valor":243,"tolerancia":1,"explicacion":"365 ÷ 1,5 ≈ 243. Cae a fines de julio o principios de agosto."}},{"slug":"consumo-1.s2.p5","orden":5,"grupo":"consumo-1.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa cuando se usa más de lo que la naturaleza regenera.","items":[{"id":"i1","texto":"Se pesca más de lo que los peces se reproducen"},{"id":"i2","texto":"La población de peces baja año a año"},{"id":"i3","texto":"Cada año hay menos para pescar"},{"id":"i4","texto":"La pesquería puede colapsar"},{"id":"i5","texto":"Los peces se reproducen más rápido cuanto más se pesca"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es la lógica de lo renovable que se agota del tronco: hasta lo que se renueva se termina si se usa más rápido."}},{"slug":"consumo-1.s2.p6","orden":6,"grupo":"consumo-1.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La huella ecológica mide solo las emisiones de CO₂.","razones":[{"id":"r1","texto":"Porque incluye cultivos, pasturas, bosques, pesca, construcciones y CO₂"},{"id":"r2","texto":"Porque solo cuenta los árboles de las ciudades"},{"id":"r3","texto":"Porque mide la cantidad de basura en kilos"}]},"solucion":{"valor":false,"explicacion":"Mide la superficie necesaria para producir alimentos, madera, fibras y pescado, para las construcciones y para absorber el CO₂. El carbono es una parte grande, pero no la única.","clave":["r1"]}},{"slug":"consumo-1.s2.p7","orden":7,"grupo":"consumo-1.s2.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada componente de la huella ecológica con lo que representa.","izquierda":[{"id":"a1","texto":"Cultivos"},{"id":"a2","texto":"Pasturas"},{"id":"a3","texto":"Zonas de pesca"},{"id":"a4","texto":"Carbono"}],"derecha":[{"id":"b1","texto":"Tierra para producir alimentos y fibras"},{"id":"b2","texto":"Tierra para el ganado"},{"id":"b3","texto":"Mar para producir pescado"},{"id":"b4","texto":"Bosque necesario para absorber el CO₂"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una sola unidad —superficie— para sumar consumos muy distintos."}},{"slug":"consumo-1.s2.p8","orden":8,"grupo":"consumo-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Desigual","cuerpo":["La huella no es igual para todos. Una persona promedio en un país de altos ingresos tiene una huella varias veces mayor que una persona promedio en un país de bajos ingresos. Y dentro de cada país, las personas con más ingresos suelen tener huellas mucho más grandes.","Por eso reducir la huella no significa lo mismo para todos: para algunos implica consumir menos; para otros, acceder a lo básico con menor impacto."]},"solucion":{}},{"slug":"consumo-1.s2.p9","orden":9,"grupo":"consumo-1.s2.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión suele tener mucho o poco efecto sobre la huella de una persona?","grupos":[{"id":"g1","nombre":"Mucho efecto"},{"id":"g2","nombre":"Poco efecto"}],"items":[{"id":"i1","texto":"Cuántos vuelos hace por año"},{"id":"i2","texto":"El color del cepillo de dientes"},{"id":"i3","texto":"Cuánta carne vacuna come"},{"id":"i4","texto":"Si usa sorbete una vez por mes"},{"id":"i5","texto":"Qué tamaño de casa calefacciona"},{"id":"i6","texto":"La marca de la birome"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los grandes consumos pesan más que los detalles. Es elegir por impacto, como en el tronco."}},{"slug":"consumo-1.s2.p10","orden":10,"grupo":"consumo-1.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un país agote su parte de la biocapacidad más temprano en el año? Marcá todo.","opciones":[{"id":"o1","texto":"Alto consumo de energía fósil por persona"},{"id":"o2","texto":"Mucho consumo de carne"},{"id":"o3","texto":"Muchos vuelos y autos por persona"},{"id":"o4","texto":"Mucho consumo de bienes nuevos"},{"id":"o5","texto":"Tener muchos parques nacionales"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El día del sobregiro de cada país depende de cuánto consume por persona."}},{"slug":"consumo-1.s2.p11","orden":11,"grupo":"consumo-1.s2.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos planetas Tierra harían falta para regenerar lo que usa hoy la humanidad.","min":0.5,"max":5,"paso":0.1,"unidad":"planetas","escala":"lineal"},"solucion":{"valor":1.7,"banda":"lineal","explicacion":"Alrededor de 1,7 según la Global Footprint Network. Con un solo planeta, la diferencia se paga agotando bosques, peces y suelos, y acumulando CO₂."}},{"slug":"consumo-1.s2.p12","orden":12,"grupo":"consumo-1.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si un país llega a su día del sobregiro en marzo, ¿qué indica?","opciones":[{"id":"o1","texto":"Que su consumo por persona es muy alto"},{"id":"o2","texto":"Que tiene muy pocos habitantes y mucha tierra"},{"id":"o3","texto":"Que sus habitantes reciclan mucho más que el resto"},{"id":"o4","texto":"Que su año empieza en otra fecha"}]},"solucion":{"clave":["o1"],"explicacion":"Cuanto antes llega la fecha, más planetas harían falta si todo el mundo consumiera como en ese país.","por_opcion":{"o3":"El reciclaje ayuda poco a la huella: lo que pesa es cuánto se consume, sobre todo energía."}}},{"slug":"consumo-1.s2.p13","orden":13,"grupo":"consumo-1.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La humanidad usa más de lo que la Tierra regenera en un año."},{"id":"s2","texto":"El día del sobregiro es el día en que se termina el petróleo."},{"id":"s3","texto":"Cada país tiene su propia fecha de sobregiro."},{"id":"s4","texto":"Todas las personas del mundo tienen la misma huella."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una idea potente, que conviene contar con precisión.","por_opcion":{"s2":"Es el día en que se agota lo que la naturaleza regenera en el año, no el petróleo.","s4":"Hay enormes diferencias entre países y dentro de cada país."}}},{"slug":"consumo-1.s2.p14","orden":14,"grupo":"consumo-1.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La humanidad usa alrededor de {{0}} planetas; el día del {{1}} marca cuándo se agota lo que la Tierra regenera en el año.","banco":[{"id":"w1","texto":"1,7"},{"id":"w2","texto":"sobregiro"},{"id":"w3","texto":"0,5"},{"id":"w4","texto":"reciclaje"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Las dos ideas centrales de la huella ecológica."}}]},{"slug":"consumo-1.s3","orden":3,"tipo":"leccion","titulo_es":"La ropa que usamos","bajada_es":"Moda rápida, agua, microfibras y prendas que se tiran: el costo escondido del placard.","minutos":11,"pasos":[{"slug":"consumo-1.s3.p1","orden":1,"grupo":"consumo-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Moda rápida","cuerpo":["La moda rápida es un modelo de negocio que lanza colecciones nuevas muy seguido, con precios bajos, para que se compre más y se use menos. Según la Fundación Ellen MacArthur, en quince años la producción de ropa se duplicó y la cantidad de veces que se usa cada prenda bajó más de un tercio.","El PNUMA estima que la industria de la moda genera entre el 2 y el 8 % de las emisiones mundiales de gases de efecto invernadero, y usa enormes cantidades de agua."],"destacado":{"valor":"2-8 %","texto":"de las emisiones mundiales de gases de efecto invernadero vendrían de la industria de la moda, según el PNUMA."}},"solucion":{}},{"slug":"consumo-1.s3.p2","orden":2,"grupo":"consumo-1.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo funciona la moda rápida.","items":[{"id":"i1","texto":"Salen colecciones nuevas muy seguido"},{"id":"i2","texto":"Las prendas son baratas y siguen la tendencia del momento"},{"id":"i3","texto":"Se compra más ropa"},{"id":"i4","texto":"Cada prenda se usa pocas veces"},{"id":"i5","texto":"Se tira mucha ropa casi nueva"},{"id":"i6","texto":"La ropa barata dura más que la cara"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un modelo que multiplica la producción y acorta la vida de cada prenda."}},{"slug":"consumo-1.s3.p3","orden":3,"grupo":"consumo-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua, químicos y microfibras","cuerpo":["El algodón necesita mucha agua y, a menudo, muchos pesticidas; hacer una remera puede requerir miles de litros de agua, contando el cultivo. El teñido usa químicos que, sin tratamiento, contaminan ríos. Y las telas sintéticas, como el poliéster, liberan microfibras plásticas en cada lavado, que terminan en ríos y mares.","Al final, gran parte de la ropa termina en rellenos o se quema: la Fundación Ellen MacArthur estimó que se entierra o se quema el equivalente a un camión de basura lleno de textiles por segundo, y que menos del 1 % del material de la ropa se recicla en ropa nueva."]},"solucion":{}},{"slug":"consumo-1.s3.p4","orden":4,"grupo":"consumo-1.s3.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué impactos ambientales tiene la ropa? Marcá todos.","opciones":[{"id":"o1","texto":"Mucha agua para cultivar algodón"},{"id":"o2","texto":"Químicos del teñido en los ríos"},{"id":"o3","texto":"Microfibras plásticas al lavar sintéticos"},{"id":"o4","texto":"Mucha ropa que termina en rellenos"},{"id":"o5","texto":"La ropa no tiene impactos porque es blanda"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Del campo al lavarropas y al relleno: impactos en cada etapa."}},{"slug":"consumo-1.s3.p5","orden":5,"grupo":"consumo-1.s3.p5","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del material de la ropa se recicla en ropa nueva, según la Fundación Ellen MacArthur.","min":0.1,"max":100,"paso":1,"unidad":"%","escala":"log"},"solucion":{"valor":1,"banda":"log","explicacion":"Menos del 1 %. La mayor parte termina en rellenos o incinerada, o se \"infrarrecicla\" en trapos y rellenos."}},{"slug":"consumo-1.s3.p6","orden":6,"grupo":"consumo-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El costo por uso","cuerpo":["Una forma útil de pensar la ropa es el costo por uso: el precio dividido la cantidad de veces que se usa. Una campera de $60.000 que se usa 200 veces cuesta $300 por uso; una de $20.000 que se usa 10 veces cuesta $2.000 por uso.","Lo mismo vale para el ambiente: una prenda que se usa muchas veces reparte su huella de fabricación entre muchos usos."]},"solucion":{}},{"slug":"consumo-1.s3.p7","orden":7,"grupo":"consumo-1.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una prenda cuesta $60.000 y se usa 200 veces. ¿Cuál es su costo por uso?","unidad":"$ por uso","decimales":0},"solucion":{"valor":300,"tolerancia":6,"explicacion":"60.000 ÷ 200 = $300 por uso. Lo barato que se usa poco puede salir caro."}},{"slug":"consumo-1.s3.p7.v2","orden":7,"grupo":"consumo-1.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una prenda cuesta $30.000 y se usa 50 veces. ¿Cuál es su costo por uso?","unidad":"$ por uso","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"30.000 ÷ 50 = $600 por uso. Lo barato que se usa poco puede salir caro."}},{"slug":"consumo-1.s3.p7.v3","orden":7,"grupo":"consumo-1.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una prenda cuesta $45.000 y se usa 150 veces. ¿Cuál es su costo por uso?","unidad":"$ por uso","decimales":0},"solucion":{"valor":300,"tolerancia":6,"explicacion":"45.000 ÷ 150 = $300 por uso. Lo barato que se usa poco puede salir caro."}},{"slug":"consumo-1.s3.p8","orden":8,"grupo":"consumo-1.s3.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas prendas por costo por uso, de más barato a más caro.","items":[{"id":"i1","texto":"Campera de $60.000 usada 300 veces"},{"id":"i2","texto":"Jean de $40.000 usado 100 veces"},{"id":"i3","texto":"Remera de $10.000 usada 10 veces"},{"id":"i4","texto":"Vestido de $30.000 usado 2 veces"}],"extremos":["Más barato por uso","Más caro por uso"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El precio de etiqueta no dice cuánto cuesta de verdad una prenda. Los usos, sí.","valores":{"i1":"$200 por uso","i2":"$400 por uso","i3":"$1.000 por uso","i4":"$15.000 por uso"}}},{"slug":"consumo-1.s3.p9","orden":9,"grupo":"consumo-1.s3.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica alarga la vida de la ropa o la acorta?","grupos":[{"id":"g1","nombre":"La alarga"},{"id":"g2","nombre":"La acorta"}],"items":[{"id":"i1","texto":"Lavar con agua fría y colgar al aire"},{"id":"i2","texto":"Lavar todo con agua caliente y secarropas"},{"id":"i3","texto":"Coser un botón o un dobladillo"},{"id":"i4","texto":"Tirar una prenda por una mancha chica"},{"id":"i5","texto":"Intercambiar ropa con amigos"},{"id":"i6","texto":"Comprar para una sola fiesta"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cuidar, reparar y hacer circular: la ropa más sustentable es la que ya existe."}},{"slug":"consumo-1.s3.p10","orden":10,"grupo":"consumo-1.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una prenda de poliéster no libera plástico mientras se usa y se lava.","razones":[{"id":"r1","texto":"Porque en cada lavado libera microfibras plásticas"},{"id":"r2","texto":"Porque el poliéster es de algodón"},{"id":"r3","texto":"Porque el agua disuelve el plástico por completo"}]},"solucion":{"valor":false,"explicacion":"En cada lavado libera microfibras plásticas que pueden llegar a ríos y mares. Lavar menos, con carga completa y agua fría, reduce la cantidad.","clave":["r1"]}},{"slug":"consumo-1.s3.p11","orden":11,"grupo":"consumo-1.s3.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estas opciones suele tener menor impacto para renovar el placard?","opciones":[{"id":"o1","texto":"Comprar ropa de segunda mano"},{"id":"o2","texto":"Comprar ropa nueva muy barata cada mes"},{"id":"o3","texto":"Comprar ropa nueva con etiqueta \"eco\" cada temporada"},{"id":"o4","texto":"Comprar ropa para cada evento y no repetirla"}]},"solucion":{"clave":["o1"],"explicacion":"La segunda mano alarga la vida de prendas que ya existen, sin fabricar nuevas.","por_opcion":{"o3":"Aunque la tela sea mejor, comprar seguido mantiene alta la producción."}}},{"slug":"consumo-1.s3.p12","orden":12,"grupo":"consumo-1.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota de moda y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"La industria de la moda tiene un impacto ambiental importante."},{"id":"s2","texto":"Comprar ropa barata seguido no tiene impacto porque es barata."},{"id":"s3","texto":"La ropa de segunda mano alarga la vida de las prendas."},{"id":"s4","texto":"Casi toda la ropa usada se recicla en ropa nueva."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El placard también es una decisión ambiental.","por_opcion":{"s2":"El precio bajo no reduce el impacto: más prendas son más recursos y residuos.","s4":"Menos del 1 % del material de la ropa se recicla en ropa nueva."}}},{"slug":"consumo-1.s3.p13","orden":13,"grupo":"consumo-1.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El precio dividido la cantidad de usos es el costo por {{0}}; las telas sintéticas liberan {{1}} al lavarse.","banco":[{"id":"w1","texto":"uso"},{"id":"w2","texto":"microfibras"},{"id":"w3","texto":"kilo"},{"id":"w4","texto":"vitaminas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para mirar el placard de otra forma."}}]},{"slug":"consumo-1.s4","orden":4,"tipo":"leccion","titulo_es":"Aparatos y objetos","bajada_es":"Celulares, notebooks y electrodomésticos: por qué la huella está en fabricarlos y qué es la obsolescencia.","minutos":9,"pasos":[{"slug":"consumo-1.s4.p1","orden":1,"grupo":"consumo-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Materiales de todo el mundo","cuerpo":["Un celular tiene decenas de materiales distintos: aluminio, cobre, oro, plata, cobalto, litio, tierras raras, plásticos y vidrio. Muchos se extraen de minas en distintos países, algunas con fuertes impactos ambientales y sociales. Fabricar los chips y las pantallas usa mucha energía y agua.","Por eso, en muchos aparatos electrónicos, la mayor parte de la huella de carbono —a menudo alrededor del 80 % en celulares— se genera antes de que lleguen a nuestras manos."],"destacado":{"valor":"≈ 80 %","texto":"de la huella de carbono de un celular suele estar en su fabricación, según los informes de los propios fabricantes."}},"solucion":{}},{"slug":"consumo-1.s4.p2","orden":2,"grupo":"consumo-1.s4.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué materiales puede tener un celular? Marcá todos.","opciones":[{"id":"o1","texto":"Cobre"},{"id":"o2","texto":"Oro"},{"id":"o3","texto":"Litio"},{"id":"o4","texto":"Cobalto"},{"id":"o5","texto":"Madera de quebracho"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un celular reúne minerales de muchas partes del mundo. Por eso fabricarlo pesa tanto."}},{"slug":"consumo-1.s4.p3","orden":3,"grupo":"consumo-1.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un celular tiene una huella total de 70 kg de CO₂e en toda su vida y el 80 % viene de la fabricación. ¿Cuántos kg son de la fabricación?","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"70 × 80 ÷ 100 = 56 kg. El uso y la carga son la parte chica."}},{"slug":"consumo-1.s4.p3.v2","orden":3,"grupo":"consumo-1.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un celular tiene una huella total de 60 kg de CO₂e en toda su vida y el 75 % viene de la fabricación. ¿Cuántos kg son de la fabricación?","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"60 × 75 ÷ 100 = 45 kg. El uso y la carga son la parte chica."}},{"slug":"consumo-1.s4.p3.v3","orden":3,"grupo":"consumo-1.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un celular tiene una huella total de 80 kg de CO₂e en toda su vida y el 85 % viene de la fabricación. ¿Cuántos kg son de la fabricación?","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":68,"tolerancia":1.36,"explicacion":"80 × 85 ÷ 100 = 68 kg. El uso y la carga son la parte chica."}},{"slug":"consumo-1.s4.p4","orden":4,"grupo":"consumo-1.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Obsolescencia","cuerpo":["Muchos aparatos se reemplazan antes de que dejen de funcionar. A veces por obsolescencia técnica: dejan de recibir actualizaciones o no hay repuestos. A veces por obsolescencia percibida: la publicidad y la moda hacen que un aparato que funciona parezca viejo.","Alargar la vida útil —con fundas, protectores, cambio de batería, reparación— es la forma más efectiva de reducir la huella de la electrónica."]},"solucion":{}},{"slug":"consumo-1.s4.p5","orden":5,"grupo":"consumo-1.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es obsolescencia técnica o percibida?","grupos":[{"id":"g1","nombre":"Técnica"},{"id":"g2","nombre":"Percibida"}],"items":[{"id":"i1","texto":"El celular deja de recibir actualizaciones de seguridad"},{"id":"i2","texto":"Salió un modelo con otro color"},{"id":"i3","texto":"No se consigue la batería de repuesto"},{"id":"i4","texto":"Tus amigos tienen uno más nuevo"},{"id":"i5","texto":"Una app que necesitás deja de funcionar en tu modelo"},{"id":"i6","texto":"La publicidad dice que el tuyo ya es viejo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La técnica se combate con repuestos, reparación y actualizaciones. La percibida, con mirar la necesidad real."}},{"slug":"consumo-1.s4.p6","orden":6,"grupo":"consumo-1.s4.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué cambiar la batería de un celular tiene tanto efecto.","items":[{"id":"i1","texto":"La batería se gasta después de un par de años"},{"id":"i2","texto":"Se cambia la batería en lugar del celular"},{"id":"i3","texto":"El celular funciona bien dos o tres años más"},{"id":"i4","texto":"Se evita fabricar un celular nuevo"},{"id":"i5","texto":"Se ahorra la mayor parte de la huella de un aparato nuevo"},{"id":"i6","texto":"Cambiar la batería duplica la huella del celular"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una pieza barata que evita fabricar un aparato entero."}},{"slug":"consumo-1.s4.p7","orden":7,"grupo":"consumo-1.s4.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un aparato viejo funciona bien, reemplazarlo por uno nuevo más eficiente siempre reduce el impacto.","razones":[{"id":"r1","texto":"Porque depende de si la huella está en la fabricación o en el uso"},{"id":"r2","texto":"Porque los aparatos nuevos no tienen huella de fabricación"},{"id":"r3","texto":"Porque los aparatos viejos no consumen energía"}]},"solucion":{"valor":false,"explicacion":"Depende de dónde está la huella. Para un celular, fabricar uno nuevo pesa más que lo que ahorra en uso. Para una heladera muy vieja e ineficiente, cambiarla puede convenir, porque su impacto está en el uso.","clave":["r1"]}},{"slug":"consumo-1.s4.p8","orden":8,"grupo":"consumo-1.s4.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada aparato con la mejor estrategia para reducir su impacto.","izquierda":[{"id":"a1","texto":"Celular"},{"id":"a2","texto":"Heladera de 25 años muy ineficiente"},{"id":"a3","texto":"Notebook lenta"},{"id":"a4","texto":"Lavarropas con una pieza rota"}],"derecha":[{"id":"b1","texto":"Usarlo más años y repararlo"},{"id":"b2","texto":"Evaluar reemplazarla por una eficiente"},{"id":"b3","texto":"Ampliar memoria o cambiar el disco"},{"id":"b4","texto":"Cambiar la pieza"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Para cada aparato, la estrategia depende de dónde está su impacto."}},{"slug":"consumo-1.s4.p9","orden":9,"grupo":"consumo-1.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué alarga la vida de un celular? Marcá todo.","opciones":[{"id":"o1","texto":"Funda y protector de pantalla"},{"id":"o2","texto":"Cambiar la batería cuando se gasta"},{"id":"o3","texto":"Mantenerlo actualizado"},{"id":"o4","texto":"Repararlo en un servicio técnico"},{"id":"o5","texto":"Cambiarlo cada vez que sale un modelo nuevo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Proteger, mantener y reparar: la vida útil se decide en el día a día."}},{"slug":"consumo-1.s4.p10","orden":10,"grupo":"consumo-1.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu notebook de cinco años anda lenta. ¿Qué conviene evaluar primero?","opciones":[{"id":"o1","texto":"Ampliar la memoria o cambiar el disco"},{"id":"o2","texto":"Comprar una nueva de inmediato"},{"id":"o3","texto":"Tirarla porque ya es vieja"},{"id":"o4","texto":"Comprar una segunda para usar las dos"}]},"solucion":{"clave":["o1"],"explicacion":"Muchas veces una mejora barata le da años más de vida.","por_opcion":{"o3":"Tirarla es la peor opción: pierde todo el valor y puede contaminar."}}},{"slug":"consumo-1.s4.p11","orden":11,"grupo":"consumo-1.s4.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de un foro y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La mayor parte de la huella de un celular está en su fabricación."},{"id":"s2","texto":"Por eso, lo mejor para el ambiente es cambiarlo todos los años."},{"id":"s3","texto":"Cambiar la batería puede alargarle la vida varios años."},{"id":"s4","texto":"Un aparato que funciona bien nunca conviene repararlo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber dónde está la huella ordena las decisiones.","por_opcion":{"s2":"Al revés: conviene usarlo más años para no fabricar otro.","s4":"Si se rompe una pieza, repararlo suele ser mejor que reemplazarlo."}}},{"slug":"consumo-1.s4.p12","orden":12,"grupo":"consumo-1.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando un aparato funciona pero parece viejo por la moda, es obsolescencia {{0}}; cuando no hay repuestos, es obsolescencia {{1}}.","banco":[{"id":"w1","texto":"percibida"},{"id":"w2","texto":"técnica"},{"id":"w3","texto":"térmica"},{"id":"w4","texto":"química"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Los dos tipos de obsolescencia, en una línea."}}]},{"slug":"consumo-1.s5","orden":5,"tipo":"leccion","titulo_es":"Comprar menos y mejor","bajada_es":"Necesidad o deseo, durabilidad, segunda mano, alquilar y compartir: herramientas para decidir antes de comprar.","minutos":12,"pasos":[{"slug":"consumo-1.s5.p1","orden":1,"grupo":"consumo-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Antes de comprar","cuerpo":["La compra con menor impacto suele ser la que no se hace. Antes de comprar algo nuevo, conviene hacerse algunas preguntas: ¿lo necesito o lo quiero por un impulso?, ¿tengo algo que cumpla la misma función?, ¿lo puedo pedir prestado, alquilar o comprar usado?, ¿cuánto lo voy a usar?, ¿cuánto va a durar?","Esperar unos días antes de una compra no urgente ayuda a separar la necesidad del impulso."]},"solucion":{}},{"slug":"consumo-1.s5.p2","orden":2,"grupo":"consumo-1.s5.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas preguntas en el orden en que conviene hacerlas antes de comprar algo.","items":[{"id":"i1","texto":"¿Lo necesito de verdad?"},{"id":"i2","texto":"¿Tengo algo que cumpla la misma función?"},{"id":"i3","texto":"¿Lo puedo pedir prestado, alquilar o comprar usado?"},{"id":"i4","texto":"Si lo compro nuevo, ¿cuál dura más y se puede reparar?"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La escalera de la jerarquía de residuos, aplicada a las compras: primero evitar, después reutilizar, y solo al final comprar nuevo y bueno."}},{"slug":"consumo-1.s5.p3","orden":3,"grupo":"consumo-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Usar sin tener","cuerpo":["Muchas cosas se usan muy poco: una taladradora se usa, en promedio, unos pocos minutos en toda su vida en una casa; un traje de fiesta, un par de veces al año. Para esas cosas, pedir prestado, alquilar o compartir entre vecinos permite usarlas sin fabricar una por casa.","Hay bibliotecas de herramientas, grupos de intercambio y alquiler de ropa de fiesta que funcionan con esta lógica."]},"solucion":{}},{"slug":"consumo-1.s5.p4","orden":4,"grupo":"consumo-1.s5.p4","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Conviene tenerlo propio o conviene pedirlo, alquilarlo o compartirlo?","grupos":[{"id":"g1","nombre":"Conviene propio"},{"id":"g2","nombre":"Conviene pedir o compartir"}],"items":[{"id":"i1","texto":"Zapatillas que usás todos los días"},{"id":"i2","texto":"Una escalera larga para una vez al año"},{"id":"i3","texto":"Una mochila para la escuela"},{"id":"i4","texto":"Un traje para un casamiento"},{"id":"i5","texto":"La heladera de casa"},{"id":"i6","texto":"Una carpa para un solo campamento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo que se usa todos los días conviene tenerlo. Lo que se usa poco, compartirlo."}},{"slug":"consumo-1.s5.p5","orden":5,"grupo":"consumo-1.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un edificio de 20 departamentos, cada uno compró una taladradora que usa pocas veces por año. Si compartieran 2 entre todos, ¿cuántas taladradoras menos harían falta?","unidad":"taladradoras","decimales":0},"solucion":{"valor":18,"tolerancia":0.5,"explicacion":"20 − 2 = 18 taladradoras menos fabricadas, con sus materiales, energía y residuos."}},{"slug":"consumo-1.s5.p5.v2","orden":5,"grupo":"consumo-1.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un edificio de 40 departamentos, cada uno compró una taladradora que usa pocas veces por año. Si compartieran 2 entre todos, ¿cuántas taladradoras menos harían falta?","unidad":"taladradoras","decimales":0},"solucion":{"valor":38,"tolerancia":0.76,"explicacion":"40 − 2 = 38 taladradoras menos fabricadas, con sus materiales, energía y residuos."}},{"slug":"consumo-1.s5.p5.v3","orden":5,"grupo":"consumo-1.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un edificio de 10 departamentos, cada uno compró una taladradora que usa pocas veces por año. Si compartieran 2 entre todos, ¿cuántas taladradoras menos harían falta?","unidad":"taladradoras","decimales":0},"solucion":{"valor":8,"tolerancia":0.5,"explicacion":"10 − 2 = 8 taladradoras menos fabricadas, con sus materiales, energía y residuos."}},{"slug":"consumo-1.s5.p6","orden":6,"grupo":"consumo-1.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Segunda mano","cuerpo":["Comprar usado alarga la vida de las cosas y evita fabricar nuevas. Muebles, ropa, libros, bicicletas, electrodomésticos y electrónica reacondicionada son opciones con mucho menor impacto y, muchas veces, menor precio.","Vender o donar lo que ya no se usa completa el círculo: otra persona lo aprovecha en lugar de comprarlo nuevo."]},"solucion":{}},{"slug":"consumo-1.s5.p7","orden":7,"grupo":"consumo-1.s5.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tiene comprar de segunda mano? Marcá todas.","opciones":[{"id":"o1","texto":"Evita fabricar un producto nuevo"},{"id":"o2","texto":"Suele ser más barato"},{"id":"o3","texto":"Alarga la vida útil de las cosas"},{"id":"o4","texto":"Reduce residuos"},{"id":"o5","texto":"Garantiza que el producto dure para siempre"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas ventajas; conviene revisar bien el estado de lo que se compra."}},{"slug":"consumo-1.s5.p8","orden":8,"grupo":"consumo-1.s5.p8","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el mercado de segunda mano reduce residuos.","items":[{"id":"i1","texto":"Alguien deja de usar una bicicleta en buen estado"},{"id":"i2","texto":"La vende en lugar de tirarla"},{"id":"i3","texto":"Otra persona la compra en lugar de una nueva"},{"id":"i4","texto":"Se fabrica una bicicleta menos"},{"id":"i5","texto":"Menos materiales, energía y residuos"},{"id":"i6","texto":"La bici usada se convierte en dos bicis nuevas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada objeto que circula es uno que no se fabrica."}},{"slug":"consumo-1.s5.p9","orden":9,"grupo":"consumo-1.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Si hay que comprar nuevo","cuerpo":["Cuando hace falta comprar nuevo, conviene elegir productos durables, que se puedan reparar, con repuestos disponibles y con garantía. Lo que dura más suele costar más al principio, pero menos por uso, como viste con la ropa."]},"solucion":{}},{"slug":"consumo-1.s5.p10","orden":10,"grupo":"consumo-1.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Necesitás una licuadora. ¿Cuál es la mejor opción si no conseguís una usada?","opciones":[{"id":"o1","texto":"Una robusta, con repuestos y garantía larga"},{"id":"o2","texto":"La más barata, aunque se rompa en meses"},{"id":"o3","texto":"La que tenga más botones y luces"},{"id":"o4","texto":"Dos licuadoras baratas por si una se rompe"}]},"solucion":{"clave":["o1"],"explicacion":"Durabilidad y reparabilidad bajan el impacto y el costo por uso.","por_opcion":{"o3":"Más funciones no significa más durabilidad."}}},{"slug":"consumo-1.s5.p11","orden":11,"grupo":"consumo-1.s5.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar más barato siempre es lo más sustentable.","razones":[{"id":"r1","texto":"Porque lo que dura poco se reemplaza más y genera más residuos"},{"id":"r2","texto":"Porque lo barato no genera residuos"},{"id":"r3","texto":"Porque lo caro siempre es sustentable"}]},"solucion":{"valor":false,"explicacion":"Si lo barato se rompe pronto y hay que reemplazarlo, termina generando más residuos y costando más por uso. La durabilidad importa.","clave":["r1"]}},{"slug":"consumo-1.s5.p12","orden":12,"grupo":"consumo-1.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta lista de propósitos y marcá lo que no ayuda a consumir mejor.","segmentos":[{"id":"s1","texto":"Esperar una semana antes de las compras no urgentes."},{"id":"s2","texto":"Aprovechar todas las ofertas aunque no necesite lo que compro."},{"id":"s3","texto":"Buscar primero en el mercado de usados."},{"id":"s4","texto":"Comprar un celular nuevo cada año para tener el último."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Consumir mejor es, sobre todo, consumir con intención.","por_opcion":{"s2":"Comprar lo que no se necesita genera impacto y gasto, aunque esté en oferta.","s4":"Aumenta mucho la huella: la mayor parte está en fabricar uno nuevo."}}},{"slug":"consumo-1.s5.p13","orden":13,"grupo":"consumo-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La compra con menor impacto suele ser la que no se {{0}}; para lo que se usa poco conviene {{1}}; y si hay que comprar nuevo, elegir algo {{2}}.","banco":[{"id":"w1","texto":"hace"},{"id":"w2","texto":"compartir"},{"id":"w3","texto":"durable"},{"id":"w4","texto":"paga"},{"id":"w5","texto":"guardar"},{"id":"w6","texto":"barato"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres criterios para comprar menos y mejor."}},{"slug":"consumo-1.s5.p14","orden":14,"grupo":"consumo-1.s5.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de conseguir una bicicleta de menor a mayor impacto.","items":[{"id":"i1","texto":"Arreglar la bici vieja que ya tenés"},{"id":"i2","texto":"Pedir prestada la de un familiar que no la usa"},{"id":"i3","texto":"Comprar una usada"},{"id":"i4","texto":"Comprar una nueva"}],"extremos":["Menor impacto","Mayor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La jerarquía de siempre: lo que ya existe, primero.","valores":{"i1":"menor impacto","i2":"muy bajo","i3":"bajo","i4":"mayor impacto"}}}]},{"slug":"consumo-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: lo que hay detrás de lo que comprás","bajada_es":"Ciclo de vida, huella ecológica, ropa, aparatos y compras, mezclados.","minutos":8,"pasos":[{"slug":"consumo-1.s6.p1","orden":1,"grupo":"consumo-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Lo que hay detrás de lo que comprás». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"consumo-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la mudanza de Valentina","bajada_es":"Valentina se muda sola por primera vez y tiene una lista de compras. Ayudala a decidir con criterio.","minutos":10,"pasos":[{"slug":"consumo-1.s7.p1","orden":1,"grupo":"consumo-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La lista","cuerpo":["Valentina tiene una lista para su nuevo departamento: heladera, cama, mesa y sillas, una taladradora para colgar cuadros, un juego de ollas, una notebook nueva (la suya tiene cuatro años y anda lenta), ropa de cama y un vestido para el casamiento de una amiga.","Tiene un presupuesto limitado. Su tía le ofrece una mesa y sillas que no usa, y en su edificio hay un grupo de vecinos que se prestan herramientas."]},"solucion":{}},{"slug":"consumo-1.s7.p2","orden":2,"grupo":"consumo-1.s7.p2","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá cada cosa de la lista según la mejor forma de conseguirla.","grupos":[{"id":"g1","nombre":"Pedir prestado o aceptar lo que ofrecen"},{"id":"g2","nombre":"Alquilar o conseguir usado"},{"id":"g3","nombre":"Comprar nuevo y eficiente"}],"items":[{"id":"i1","texto":"Mesa y sillas de la tía"},{"id":"i2","texto":"Vestido para el casamiento"},{"id":"i3","texto":"Heladera"},{"id":"i4","texto":"Taladradora del grupo de vecinos"},{"id":"i5","texto":"Juego de ollas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2"},"explicacion":"Cada cosa tiene su mejor opción. La heladera nueva y eficiente se justifica porque su impacto está en el uso durante muchos años."}},{"slug":"consumo-1.s7.p3","orden":3,"grupo":"consumo-1.s7.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene con la notebook de cuatro años que anda lenta?","opciones":[{"id":"o1","texto":"Probar ampliar la memoria o cambiar el disco"},{"id":"o2","texto":"Comprar una nueva sin revisar la vieja"},{"id":"o3","texto":"Tirarla con la basura común"},{"id":"o4","texto":"Comprar dos nuevas por si una falla"}]},"solucion":{"clave":["o1"],"explicacion":"Una mejora barata puede darle años más de vida y evitar la huella de fabricar otra.","por_opcion":{"o3":"Además de desperdiciarla, los electrónicos no van con la basura común."}}},{"slug":"consumo-1.s7.p4","orden":4,"grupo":"consumo-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para la heladera, compara una que consume 300 kWh por año con otra de 600. Si la usa 12 años, ¿cuántos kWh ahorra con la eficiente?","unidad":"kWh","decimales":0},"solucion":{"valor":3600,"tolerancia":72,"explicacion":"(600 − 300) × 12 = 3.600 kWh. En una heladera, el uso pesa mucho: por eso conviene la eficiente."}},{"slug":"consumo-1.s7.p4.v2","orden":4,"grupo":"consumo-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para la heladera, compara una que consume 250 kWh por año con otra de 500. Si la usa 10 años, ¿cuántos kWh ahorra con la eficiente?","unidad":"kWh","decimales":0},"solucion":{"valor":2500,"tolerancia":50,"explicacion":"(500 − 250) × 10 = 2.500 kWh. En una heladera, el uso pesa mucho: por eso conviene la eficiente."}},{"slug":"consumo-1.s7.p4.v3","orden":4,"grupo":"consumo-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para la heladera, compara una que consume 350 kWh por año con otra de 650. Si la usa 14 años, ¿cuántos kWh ahorra con la eficiente?","unidad":"kWh","decimales":0},"solucion":{"valor":4200,"tolerancia":84,"explicacion":"(650 − 350) × 14 = 4.200 kWh. En una heladera, el uso pesa mucho: por eso conviene la eficiente."}},{"slug":"consumo-1.s7.p5","orden":5,"grupo":"consumo-1.s7.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vestido nuevo cuesta $80.000 y lo usaría una sola vez. Alquilarlo cuesta $15.000. ¿Cuánto ahorra alquilando?","unidad":"$","decimales":0},"solucion":{"valor":65000,"tolerancia":1300,"explicacion":"80.000 − 15.000 = $65.000. Y se evita fabricar una prenda que se usaría una vez."}},{"slug":"consumo-1.s7.p5.v2","orden":5,"grupo":"consumo-1.s7.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vestido nuevo cuesta $60.000 y lo usaría una sola vez. Alquilarlo cuesta $12.000. ¿Cuánto ahorra alquilando?","unidad":"$","decimales":0},"solucion":{"valor":48000,"tolerancia":960,"explicacion":"60.000 − 12.000 = $48.000. Y se evita fabricar una prenda que se usaría una vez."}},{"slug":"consumo-1.s7.p5.v3","orden":5,"grupo":"consumo-1.s7.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vestido nuevo cuesta $100.000 y lo usaría una sola vez. Alquilarlo cuesta $20.000. ¿Cuánto ahorra alquilando?","unidad":"$","decimales":0},"solucion":{"valor":80000,"tolerancia":1600,"explicacion":"100.000 − 20.000 = $80.000. Y se evita fabricar una prenda que se usaría una vez."}},{"slug":"consumo-1.s7.p6","orden":6,"grupo":"consumo-1.s7.p6","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las decisiones de Valentina por cuánto impacto evitan, de más a menos.","items":[{"id":"i1","texto":"Reparar la notebook en vez de comprar una nueva"},{"id":"i2","texto":"Aceptar la mesa y sillas de la tía"},{"id":"i3","texto":"Alquilar el vestido"},{"id":"i4","texto":"Pedir la taladradora prestada"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Todas ayudan. Las que evitan fabricar objetos grandes o con mucha huella de fabricación pesan más.","valores":{"i1":"evita fabricar un aparato electrónico","i2":"evita fabricar muebles","i3":"evita una prenda de un solo uso","i4":"evita una herramienta de poco uso"}}},{"slug":"consumo-1.s7.p7","orden":7,"grupo":"consumo-1.s7.p7","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Valentina escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Acepto la mesa y las sillas de mi tía."},{"id":"s2","texto":"Compro la heladera más barata aunque consuma el doble."},{"id":"s3","texto":"Pido la taladradora al grupo de vecinos."},{"id":"s4","texto":"Tiro la notebook vieja con la basura y compro otra."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan combina reutilizar, compartir y comprar bien lo que hace falta.","por_opcion":{"s2":"Su impacto y su costo están en el uso: conviene la eficiente.","s4":"Conviene intentar mejorarla; y si se descarta, va a un punto de electrónicos."}}},{"slug":"consumo-1.s7.p8","orden":8,"grupo":"consumo-1.s7.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué criterios usó Valentina para decidir bien? Marcá todos.","opciones":[{"id":"o1","texto":"Preguntarse si lo necesitaba"},{"id":"o2","texto":"Aprovechar lo que ya existe"},{"id":"o3","texto":"Compartir lo que se usa poco"},{"id":"o4","texto":"Comprar eficiente lo que consume energía"},{"id":"o5","texto":"Comprar todo nuevo para estrenar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los criterios de toda la unidad, aplicados a una mudanza real."}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"consumo-2","rama":"consumo","orden":2,"nivel":1,"titulo_es":"Etiquetas, sellos y greenwashing","bajada_es":"\"Eco\", \"natural\", \"verde\", \"biodegradable\": qué dicen de verdad las etiquetas, qué sellos valen y cómo reconocer el lavado verde.","objetivos_es":["Leer la información obligatoria y el etiquetado frontal de los alimentos","Distinguir certificaciones independientes de autodeclaraciones","Reconocer las formas más comunes de greenwashing","Interpretar correctamente términos como biodegradable, compostable y reciclable","Evaluar un producto completo con una lista de preguntas"],"repasa":["consumo-1","tronco-3"],"requiere_tronco":1,"fuentes":["ley-27642-etiquetado","ce-green-claims","senasa-organicos","unep-plasticos","ellen-macarthur"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-2.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que dicen las etiquetas","bajada_es":"Información obligatoria, ingredientes y el etiquetado frontal de alimentos en Argentina.","minutos":9,"pasos":[{"slug":"consumo-2.s1.p1","orden":1,"grupo":"consumo-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo obligatorio","cuerpo":["Los productos tienen información obligatoria: qué son, quién los fabrica, el contenido neto, la fecha de vencimiento y, en los alimentos, la lista de ingredientes (ordenados de mayor a menor cantidad) y la información nutricional.","Esa información está regulada y controlada. Otra cosa son las frases de marketing del frente del envase, que muchas veces no tienen controles tan estrictos."]},"solucion":{}},{"slug":"consumo-2.s1.p2","orden":2,"grupo":"consumo-2.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En la lista de ingredientes de un alimento, ¿qué indica el orden?","opciones":[{"id":"o1","texto":"De mayor a menor cantidad"},{"id":"o2","texto":"De más sano a menos sano"},{"id":"o3","texto":"El orden en que se agregan en la fábrica"},{"id":"o4","texto":"Por orden alfabético"}]},"solucion":{"clave":["o1"],"explicacion":"Si el azúcar aparece primero, es el ingrediente principal. Leer los primeros ingredientes dice mucho.","por_opcion":{"o3":"La norma pide ordenarlos por cantidad, no por el proceso."}}},{"slug":"consumo-2.s1.p3","orden":3,"grupo":"consumo-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El etiquetado frontal","cuerpo":["En Argentina, la Ley 27.642 de Promoción de la Alimentación Saludable estableció sellos negros con forma de octógono en el frente de los alimentos y bebidas que superan ciertos límites: \"exceso en azúcares\", \"exceso en sodio\", \"exceso en grasas saturadas\", \"exceso en grasas totales\" y \"exceso en calorías\". También leyendas de advertencia cuando contienen edulcorantes o cafeína, no recomendables para chicos.","Los sellos permiten comparar productos de un vistazo. Cuantos menos sellos, en general, mejor perfil nutricional."],"lista":["Exceso en azúcares","Exceso en sodio","Exceso en grasas saturadas","Exceso en grasas totales","Exceso en calorías"]},"solucion":{}},{"slug":"consumo-2.s1.p4","orden":4,"grupo":"consumo-2.s1.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos son sellos del etiquetado frontal argentino? Marcá todos.","opciones":[{"id":"o1","texto":"Exceso en azúcares"},{"id":"o2","texto":"Exceso en sodio"},{"id":"o3","texto":"Exceso en grasas saturadas"},{"id":"o4","texto":"Exceso en calorías"},{"id":"o5","texto":"Exceso en vitaminas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los sellos advierten sobre nutrientes críticos para la salud. Las vitaminas no tienen sello de exceso."}},{"slug":"consumo-2.s1.p5","orden":5,"grupo":"consumo-2.s1.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta información es obligatoria y controlada o es marketing del envase?","grupos":[{"id":"g1","nombre":"Obligatoria"},{"id":"g2","nombre":"Marketing"}],"items":[{"id":"i1","texto":"Lista de ingredientes"},{"id":"i2","texto":"\"Receta de la abuela\""},{"id":"i3","texto":"Fecha de vencimiento"},{"id":"i4","texto":"\"El sabor de siempre\""},{"id":"i5","texto":"Sellos de advertencia"},{"id":"i6","texto":"Dibujo de una granja feliz"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo obligatorio informa; el marketing seduce. Conviene leer primero lo obligatorio."}},{"slug":"consumo-2.s1.p6","orden":6,"grupo":"consumo-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cereal tiene 3 sellos de advertencia y otro 1. ¿Cuántos sellos de diferencia hay?","unidad":"sellos","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"3 − 1 = 2. Comparar sellos entre productos parecidos es una forma rápida de elegir el de mejor perfil."}},{"slug":"consumo-2.s1.p6.v2","orden":6,"grupo":"consumo-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cereal tiene 2 sellos de advertencia y otro 0. ¿Cuántos sellos de diferencia hay?","unidad":"sellos","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"2 − 0 = 2. Comparar sellos entre productos parecidos es una forma rápida de elegir el de mejor perfil."}},{"slug":"consumo-2.s1.p6.v3","orden":6,"grupo":"consumo-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cereal tiene 4 sellos de advertencia y otro 2. ¿Cuántos sellos de diferencia hay?","unidad":"sellos","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"4 − 2 = 2. Comparar sellos entre productos parecidos es una forma rápida de elegir el de mejor perfil."}},{"slug":"consumo-2.s1.p7","orden":7,"grupo":"consumo-2.s1.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un producto sin sellos de advertencia es siempre el más saludable de la góndola.","razones":[{"id":"r1","texto":"Porque los sellos no evalúan todas las características del alimento"},{"id":"r2","texto":"Porque los productos sin sellos tienen más azúcar"},{"id":"r3","texto":"Porque los sellos son solo decoración"}]},"solucion":{"valor":false,"explicacion":"Los sellos advierten excesos de ciertos nutrientes, pero no evalúan todo. Un producto sin sellos puede igual ser ultraprocesado o poco nutritivo; conviene mirar también los ingredientes.","clave":["r1"]}},{"slug":"consumo-2.s1.p8","orden":8,"grupo":"consumo-2.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el etiquetado frontal cambia lo que se vende.","items":[{"id":"i1","texto":"Los productos con exceso de nutrientes críticos llevan sellos"},{"id":"i2","texto":"Los compradores los identifican de un vistazo"},{"id":"i3","texto":"Muchos eligen opciones con menos sellos"},{"id":"i4","texto":"Algunas empresas reformulan sus productos para evitar sellos"},{"id":"i5","texto":"Los sellos obligan a cada persona a comer sano"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Como la etiqueta de eficiencia energética: no obliga a nadie, pero cambia lo que se elige y lo que se fabrica."}},{"slug":"consumo-2.s1.p9","orden":9,"grupo":"consumo-2.s1.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada dato de la etiqueta con lo que te dice.","izquierda":[{"id":"a1","texto":"Primer ingrediente de la lista"},{"id":"a2","texto":"Octógono negro"},{"id":"a3","texto":"Fecha de vencimiento"},{"id":"a4","texto":"Contenido neto"}],"derecha":[{"id":"b1","texto":"El ingrediente principal"},{"id":"b2","texto":"Exceso de un nutriente crítico"},{"id":"b3","texto":"Hasta cuándo es seguro consumirlo"},{"id":"b4","texto":"Cuánto producto trae el envase"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro datos que conviene mirar antes que las fotos del envase."}},{"slug":"consumo-2.s1.p10","orden":10,"grupo":"consumo-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este análisis de un yogur y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Tiene un sello de exceso en azúcares."},{"id":"s2","texto":"El envase dice \"natural\", así que no puede tener azúcar agregada."},{"id":"s3","texto":"El primer ingrediente es leche."},{"id":"s4","texto":"Como tiene una vaca dibujada, es el más saludable."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Leer primero lo obligatorio, y desconfiar del marketing.","por_opcion":{"s2":"\"Natural\" no es una garantía: hay que leer los ingredientes.","s4":"El dibujo es marketing; lo que informa es la etiqueta."}}},{"slug":"consumo-2.s1.p11","orden":11,"grupo":"consumo-2.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los ingredientes se ordenan de mayor a menor {{0}}; los sellos negros de la Ley 27.642 tienen forma de {{1}}.","banco":[{"id":"w1","texto":"cantidad"},{"id":"w2","texto":"octógono"},{"id":"w3","texto":"precio"},{"id":"w4","texto":"círculo"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos claves para leer un alimento en segundos."}},{"slug":"consumo-2.s1.p12","orden":12,"grupo":"consumo-2.s1.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos cereales de mejor a peor perfil según sus sellos.","items":[{"id":"i1","texto":"Avena sin sellos"},{"id":"i2","texto":"Copos con un sello de exceso en sodio"},{"id":"i3","texto":"Copos azucarados con dos sellos"},{"id":"i4","texto":"Cereal de colores con cuatro sellos"}],"extremos":["Mejor perfil","Peor perfil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Menos sellos, en general, mejor perfil. Es una primera comparación rápida.","valores":{"i1":"ningún sello","i2":"un sello","i3":"dos sellos","i4":"cuatro sellos"}}}]},{"slug":"consumo-2.s2","orden":2,"tipo":"leccion","titulo_es":"Sellos ambientales","bajada_es":"Certificaciones independientes, sellos de la propia marca y cómo saber cuál vale.","minutos":11,"pasos":[{"slug":"consumo-2.s2.p1","orden":1,"grupo":"consumo-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién certifica","cuerpo":["Un sello ambiental dice que un producto cumple ciertas condiciones. Lo importante es quién lo dice. Hay tres tipos: las certificaciones de tercera parte, otorgadas por un organismo independiente que audita con normas públicas; las autodeclaraciones, en las que la propia empresa afirma algo sobre su producto; y los sellos inventados, que parecen certificaciones pero no tienen respaldo.","Las certificaciones de tercera parte son las más confiables porque alguien ajeno a la empresa verifica que se cumpla."]},"solucion":{}},{"slug":"consumo-2.s2.p2","orden":2,"grupo":"consumo-2.s2.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una certificación independiente o una autodeclaración?","grupos":[{"id":"g1","nombre":"Certificación independiente"},{"id":"g2","nombre":"Autodeclaración"}],"items":[{"id":"i1","texto":"Sello de producto orgánico certificado"},{"id":"i2","texto":"\"Amigable con el planeta\" escrito por la marca"},{"id":"i3","texto":"Sello de manejo forestal responsable (FSC) en un papel"},{"id":"i4","texto":"Una hojita verde diseñada por la empresa"},{"id":"i5","texto":"Etiqueta oficial de eficiencia energética"},{"id":"i6","texto":"\"Hecho con conciencia\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Una certificación tiene detrás una norma pública y alguien que audita. Una autodeclaración, solo la palabra de la empresa."}},{"slug":"consumo-2.s2.p3","orden":3,"grupo":"consumo-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Algunos sellos conocidos","cuerpo":["El sello FSC en papel y madera indica que proviene de bosques manejados según ciertas normas ambientales y sociales. Los productos orgánicos certificados en Argentina los controla el SENASA a través de certificadoras autorizadas, y pueden llevar el sello \"Orgánico Argentina\". La etiqueta de eficiencia energética, que viste en la rama de Energía, es obligatoria para muchos aparatos. El sello de Comercio Justo indica condiciones de pago y trabajo para productores."]},"solucion":{}},{"slug":"consumo-2.s2.p4","orden":4,"grupo":"consumo-2.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sello con lo que certifica.","izquierda":[{"id":"a1","texto":"FSC"},{"id":"a2","texto":"Orgánico Argentina"},{"id":"a3","texto":"Etiqueta de eficiencia energética"},{"id":"a4","texto":"Comercio Justo"}],"derecha":[{"id":"b1","texto":"Madera y papel de bosques bien manejados"},{"id":"b2","texto":"Producción orgánica controlada por el SENASA"},{"id":"b3","texto":"Consumo de energía de un aparato"},{"id":"b4","texto":"Condiciones justas para productores"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada sello certifica algo concreto. Ninguno certifica que un producto sea \"bueno para el planeta\" en todo."}},{"slug":"consumo-2.s2.p5","orden":5,"grupo":"consumo-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un producto con un sello orgánico certificado no tiene ningún impacto ambiental.","razones":[{"id":"r1","texto":"Porque certifica una forma de producción, no impacto cero"},{"id":"r2","texto":"Porque lo orgánico no usa tierra"},{"id":"r3","texto":"Porque los sellos garantizan que el producto no tiene huella"}]},"solucion":{"valor":false,"explicacion":"Certifica cómo se produjo (sin ciertos agroquímicos, por ejemplo), pero igual usa tierra, agua, energía y envases. Ningún sello significa impacto cero.","clave":["r1"]}},{"slug":"consumo-2.s2.p6","orden":6,"grupo":"consumo-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo verificar un sello","cuerpo":["Para saber si un sello vale, conviene preguntarse: ¿quién lo otorga?, ¿es independiente de la empresa?, ¿las normas son públicas?, ¿se puede verificar en la página del organismo que el producto está certificado?, ¿qué aspecto certifica exactamente?","Si el sello no tiene nombre de organismo, no remite a ninguna norma o solo dice palabras vagas, probablemente sea marketing."]},"solucion":{}},{"slug":"consumo-2.s2.p7","orden":7,"grupo":"consumo-2.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas ayudan a saber si un sello es confiable? Marcá todas.","opciones":[{"id":"o1","texto":"¿Quién lo otorga?"},{"id":"o2","texto":"¿Es independiente de la empresa?"},{"id":"o3","texto":"¿Sus normas son públicas?"},{"id":"o4","texto":"¿Se puede verificar el producto en la página del organismo?"},{"id":"o5","texto":"¿Es de color verde?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El color verde no certifica nada. La independencia y la transparencia, sí."}},{"slug":"consumo-2.s2.p8","orden":8,"grupo":"consumo-2.s2.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para verificar un sello desconocido.","items":[{"id":"i1","texto":"Leer el nombre del organismo que lo otorga"},{"id":"i2","texto":"Buscar la página oficial de ese organismo"},{"id":"i3","texto":"Revisar qué norma certifica"},{"id":"i4","texto":"Verificar si el producto figura como certificado"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuatro pasos que llevan pocos minutos y separan sellos reales de dibujos."}},{"slug":"consumo-2.s2.p9","orden":9,"grupo":"consumo-2.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un detergente tiene un dibujo de una hoja con la frase \"eco-friendly\" y ningún organismo nombrado. ¿Qué es lo más probable?","opciones":[{"id":"o1","texto":"Que sea una autodeclaración de marketing"},{"id":"o2","texto":"Que esté certificado por un organismo internacional"},{"id":"o3","texto":"Que sea obligatorio por ley ponerlo"},{"id":"o4","texto":"Que el producto sea biodegradable al 100 %"}]},"solucion":{"clave":["o1"],"explicacion":"Sin organismo ni norma, un dibujo verde es solo diseño.","por_opcion":{"o3":"No hay ninguna ley que exija ese dibujo: es una decisión de la marca."}}},{"slug":"consumo-2.s2.p10","orden":10,"grupo":"consumo-2.s2.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo funciona una certificación de tercera parte.","items":[{"id":"i1","texto":"Una organización independiente publica una norma"},{"id":"i2","texto":"La empresa pide ser auditada"},{"id":"i3","texto":"Un auditor verifica que cumpla la norma"},{"id":"i4","texto":"Si cumple, puede usar el sello"},{"id":"i5","texto":"Se hacen auditorías periódicas para mantenerlo"},{"id":"i6","texto":"La empresa diseña el sello y se lo pone sola"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Independencia, norma pública y controles periódicos: lo que da valor a un sello."}},{"slug":"consumo-2.s2.p11","orden":11,"grupo":"consumo-2.s2.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un sello que dice \"certificado\" siempre fue otorgado por un organismo independiente.","razones":[{"id":"r1","texto":"Porque la palabra sola no dice quién certificó"},{"id":"r2","texto":"Porque la palabra \"certificado\" está prohibida"},{"id":"r3","texto":"Porque todos los sellos son oficiales"}]},"solucion":{"valor":false,"explicacion":"Cualquiera puede escribir \"certificado\" en un envase. Hay que ver quién lo otorga y si se puede verificar.","clave":["r1"]}},{"slug":"consumo-2.s2.p12","orden":12,"grupo":"consumo-2.s2.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos sellos del más confiable al menos confiable.","items":[{"id":"i1","texto":"Certificación de tercera parte con norma pública y registro verificable"},{"id":"i2","texto":"Certificación de tercera parte sin registro online"},{"id":"i3","texto":"Autodeclaración con datos concretos"},{"id":"i4","texto":"Dibujo verde sin organismo ni datos"}],"extremos":["Más confiable","Menos confiable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Independencia, norma pública y posibilidad de verificar: los tres pilares de un sello confiable.","valores":{"i1":"muy confiable","i2":"confiable","i3":"poco confiable","i4":"nada confiable"}}},{"slug":"consumo-2.s2.p13","orden":13,"grupo":"consumo-2.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un envase y marcá lo que no es una certificación real.","segmentos":[{"id":"s1","texto":"Sello FSC con número de licencia verificable."},{"id":"s2","texto":"Hojita verde con la frase \"producto responsable\"."},{"id":"s3","texto":"Etiqueta de eficiencia energética clase A."},{"id":"s4","texto":"\"Certificado por nuestro equipo de sustentabilidad\"."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Quien certifica importa tanto como lo que certifica.","por_opcion":{"s2":"Es una autodeclaración sin organismo ni norma.","s4":"Si lo certifica la propia empresa, no es independiente."}}},{"slug":"consumo-2.s2.p14","orden":14,"grupo":"consumo-2.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las certificaciones de tercera {{0}} son otorgadas por organismos {{1}}; cuando lo dice la propia marca, es una {{2}}.","banco":[{"id":"w1","texto":"parte"},{"id":"w2","texto":"independientes"},{"id":"w3","texto":"autodeclaración"},{"id":"w4","texto":"página"},{"id":"w5","texto":"empresariales"},{"id":"w6","texto":"ley"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres tipos de sellos ambientales, resumidos en una línea."}}]},{"slug":"consumo-2.s3","orden":3,"tipo":"leccion","titulo_es":"El lavado verde","bajada_es":"Frases vagas, datos escondidos y comparaciones tramposas: las formas más comunes de greenwashing.","minutos":9,"pasos":[{"slug":"consumo-2.s3.p1","orden":1,"grupo":"consumo-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es el greenwashing","cuerpo":["El greenwashing, o lavado verde, es presentar un producto, un servicio o una empresa como más amigable con el ambiente de lo que realmente es. Es muy común: un estudio de la Comisión Europea encontró que más de la mitad de las afirmaciones ambientales analizadas en productos eran vagas, engañosas o sin fundamento.","Por eso varios países están regulando estas afirmaciones y exigiendo pruebas."],"destacado":{"valor":"> 50 %","texto":"de las afirmaciones ambientales analizadas por la Comisión Europea eran vagas, engañosas o sin fundamento."}},"solucion":{}},{"slug":"consumo-2.s3.p2","orden":2,"grupo":"consumo-2.s3.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las afirmaciones ambientales analizadas por la Comisión Europea resultaron vagas, engañosas o sin fundamento.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":53,"banda":"lineal","explicacion":"Alrededor del 53 %. Más de la mitad: por eso conviene leer con ojo crítico."}},{"slug":"consumo-2.s3.p3","orden":3,"grupo":"consumo-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las trampas más comunes","cuerpo":["Algunas formas típicas: palabras vagas sin significado concreto (\"natural\", \"eco\", \"verde\"); destacar un aspecto chico y esconder los grandes (una botella con 10 % de plástico reciclado de una bebida en envase descartable); afirmaciones sin pruebas; datos irrelevantes (\"sin CFC\", cuando están prohibidos hace décadas); sellos inventados; y comparaciones engañosas (\"el menos contaminante de su categoría\" en una categoría muy contaminante)."]},"solucion":{}},{"slug":"consumo-2.s3.p4","orden":4,"grupo":"consumo-2.s3.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ejemplo con la trampa que usa.","izquierda":[{"id":"a1","texto":"\"100 % natural\" sin explicar nada"},{"id":"a2","texto":"\"Sin CFC\" en un aerosol actual"},{"id":"a3","texto":"\"El SUV más eficiente de su clase\""},{"id":"a4","texto":"Envase con 10 % de plástico reciclado presentado como solución"}],"derecha":[{"id":"b1","texto":"Palabra vaga"},{"id":"b2","texto":"Dato irrelevante: están prohibidos"},{"id":"b3","texto":"Comparación dentro de una categoría de alto impacto"},{"id":"b4","texto":"Destacar lo chico y esconder lo grande"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Reconocer la trampa es el primer paso para no caer en ella."}},{"slug":"consumo-2.s3.p5","orden":5,"grupo":"consumo-2.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un aerosol que dice \"sin CFC\" es mejor para el ambiente que los demás aerosoles del mercado.","razones":[{"id":"r1","texto":"Porque los CFC están prohibidos y ningún aerosol actual los tiene"},{"id":"r2","texto":"Porque los CFC son buenos para la capa de ozono"},{"id":"r3","texto":"Porque todos los aerosoles actuales tienen CFC"}]},"solucion":{"valor":false,"explicacion":"Los CFC están prohibidos por el Protocolo de Montreal: ningún aerosol actual los tiene. Es un dato cierto pero irrelevante, que se usa para parecer mejor.","clave":["r1"]}},{"slug":"consumo-2.s3.p6","orden":6,"grupo":"consumo-2.s3.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una afirmación concreta y verificable o vaga?","grupos":[{"id":"g1","nombre":"Concreta y verificable"},{"id":"g2","nombre":"Vaga"}],"items":[{"id":"i1","texto":"Envase con 50 % de plástico reciclado certificado"},{"id":"i2","texto":"Amigable con el planeta"},{"id":"i3","texto":"Consume 180 kWh por año según la etiqueta oficial"},{"id":"i4","texto":"Pensado para el futuro"},{"id":"i5","texto":"Madera con certificación FSC número verificable"},{"id":"i6","texto":"Producto consciente"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Una afirmación útil dice qué, cuánto y quién lo verifica."}},{"slug":"consumo-2.s3.p7","orden":7,"grupo":"consumo-2.s3.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo funciona el greenwashing.","items":[{"id":"i1","texto":"Una empresa destaca un aspecto verde menor de su producto"},{"id":"i2","texto":"Los compradores creen que el producto es sustentable"},{"id":"i3","texto":"Lo eligen por sobre alternativas realmente mejores"},{"id":"i4","texto":"Las alternativas mejores venden menos"},{"id":"i5","texto":"Se frena el cambio hacia productos de menor impacto"},{"id":"i6","texto":"El greenwashing hace que los productos sean más verdes"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El greenwashing no solo engaña: desvía la demanda de lo que realmente sirve."}},{"slug":"consumo-2.s3.p8","orden":8,"grupo":"consumo-2.s3.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una aerolínea dice que sus vuelos son \"carbono neutrales\" porque planta árboles. ¿Qué conviene preguntar?","opciones":[{"id":"o1","texto":"¿Cuánto compensa y con qué garantías?"},{"id":"o2","texto":"¿De qué color son los asientos de sus aviones?"},{"id":"o3","texto":"¿Por qué no plantan más árboles?"},{"id":"o4","texto":"¿Cuántos pasajeros tiene cada vuelo?"}]},"solucion":{"clave":["o1"],"explicacion":"Las compensaciones pueden ser reales o dudosas: árboles que se queman, que se iban a plantar igual o que tardan décadas en absorber lo emitido.","por_opcion":{"o3":"Más árboles no resuelve las dudas: hay que saber si las compensaciones son reales y duraderas."}}},{"slug":"consumo-2.s3.p9","orden":9,"grupo":"consumo-2.s3.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales indican posible greenwashing? Marcá todas.","opciones":[{"id":"o1","texto":"Palabras vagas como \"eco\" o \"natural\" sin datos"},{"id":"o2","texto":"Sellos sin organismo ni norma"},{"id":"o3","texto":"Destacar un detalle verde y esconder el impacto principal"},{"id":"o4","texto":"Afirmaciones sin pruebas verificables"},{"id":"o5","texto":"Datos concretos con fuente independiente"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los datos concretos con fuente son lo contrario del greenwashing."}},{"slug":"consumo-2.s3.p10","orden":10,"grupo":"consumo-2.s3.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo que es greenwashing.","segmentos":[{"id":"s1","texto":"Nuestra botella usa un 30 % de plástico reciclado, certificado."},{"id":"s2","texto":"Somos una marca 100 % comprometida con el planeta."},{"id":"s3","texto":"El envase se puede reciclar donde hay recolección de PET."},{"id":"s4","texto":"Nuestra bebida es ecológica porque la tapa es verde."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo concreto informa; lo vago, en cambio, solo vende.","por_opcion":{"s2":"Frase vaga sin datos que la respalden.","s4":"El color de la tapa no cambia el impacto del producto."}}},{"slug":"consumo-2.s3.p11","orden":11,"grupo":"consumo-2.s3.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Presentar algo como más verde de lo que es se llama {{0}}; una afirmación útil es concreta y {{1}}.","banco":[{"id":"w1","texto":"greenwashing"},{"id":"w2","texto":"verificable"},{"id":"w3","texto":"reciclaje"},{"id":"w4","texto":"emotiva"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de la lección, en una línea."}},{"slug":"consumo-2.s3.p12","orden":12,"grupo":"consumo-2.s3.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas afirmaciones de la más confiable a la menos.","items":[{"id":"i1","texto":"Dato con certificación independiente verificable"},{"id":"i2","texto":"Dato concreto sin certificación, con la metodología publicada"},{"id":"i3","texto":"Frase vaga con un dibujo de hojas"},{"id":"i4","texto":"Sello inventado que imita a uno oficial"}],"extremos":["Más confiable","Menos confiable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La confianza crece con la concreción y la independencia de quien verifica.","valores":{"i1":"muy confiable","i2":"algo confiable","i3":"poco confiable","i4":"engañosa"}}}]},{"slug":"consumo-2.s4","orden":4,"tipo":"leccion","titulo_es":"Palabras que confunden","bajada_es":"Biodegradable, compostable, reciclable, reciclado y \"degradable\": qué significa cada una de verdad.","minutos":11,"pasos":[{"slug":"consumo-2.s4.p1","orden":1,"grupo":"consumo-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclable y reciclado","cuerpo":["\"Reciclable\" significa que el material se podría reciclar, si hay un sistema que lo recoja y un mercado que lo compre. \"Reciclado\" significa que el producto está hecho, en parte o en todo, con material que ya fue reciclado. Son cosas distintas: un envase puede ser reciclable y terminar en el relleno, y un producto puede tener contenido reciclado sin ser reciclable después.","El símbolo de las tres flechas en círculo no garantiza nada por sí solo; hay que ver qué dice al lado."]},"solucion":{}},{"slug":"consumo-2.s4.p2","orden":2,"grupo":"consumo-2.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su significado.","izquierda":[{"id":"a1","texto":"Reciclable"},{"id":"a2","texto":"Reciclado"},{"id":"a3","texto":"Contenido reciclado 30 %"}],"derecha":[{"id":"b1","texto":"Se podría reciclar si hay sistema y mercado"},{"id":"b2","texto":"Está hecho con material ya reciclado"},{"id":"b3","texto":"Un 30 % del material viene de reciclaje"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Dos palabras que se parecen mucho y dicen cosas muy distintas."}},{"slug":"consumo-2.s4.p3","orden":3,"grupo":"consumo-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Biodegradable y compostable","cuerpo":["\"Biodegradable\" significa que microorganismos pueden descomponer el material, pero no dice en cuánto tiempo ni en qué condiciones: casi todo se biodegrada en algún momento. Por eso la palabra sola dice poco.","\"Compostable\" es más preciso: el material se descompone en condiciones de compostaje en un tiempo determinado, según una norma. Pero muchos productos compostables necesitan compostaje industrial, con temperaturas altas: en una compostera casera o en el relleno pueden durar mucho."]},"solucion":{}},{"slug":"consumo-2.s4.p4","orden":4,"grupo":"consumo-2.s4.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un plástico \"biodegradable\" desaparece en pocas semanas en cualquier lugar.","razones":[{"id":"r1","texto":"Porque se degrada solo en ciertas condiciones y tiempos"},{"id":"r2","texto":"Porque lo biodegradable no se degrada nunca"},{"id":"r3","texto":"Porque todo plástico desaparece en semanas"}]},"solucion":{"valor":false,"explicacion":"Depende de las condiciones: temperatura, humedad, microorganismos. En el mar, en un relleno o en una compostera casera puede durar muchísimo.","clave":["r1"]}},{"slug":"consumo-2.s4.p5","orden":5,"grupo":"consumo-2.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los \"oxodegradables\"","cuerpo":["Los plásticos \"oxodegradables\" u \"oxobiodegradables\" tienen aditivos que los hacen romperse en pedazos cada vez más chicos. No desaparecen: se convierten en microplásticos. Por eso la Unión Europea los prohibió en 2021, y muchos especialistas los consideran peores que el plástico común."]},"solucion":{}},{"slug":"consumo-2.s4.p6","orden":6,"grupo":"consumo-2.s4.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué le pasa a una bolsa oxodegradable tirada en el campo.","items":[{"id":"i1","texto":"La bolsa se expone al sol y al aire"},{"id":"i2","texto":"Los aditivos hacen que se fragmente"},{"id":"i3","texto":"Se rompe en pedazos cada vez más chicos"},{"id":"i4","texto":"Quedan microplásticos en el suelo y el agua"},{"id":"i5","texto":"La bolsa se convierte en abono para las plantas"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Romperse no es desaparecer. Los microplásticos son más difíciles de recoger que la bolsa entera."}},{"slug":"consumo-2.s4.p7","orden":7,"grupo":"consumo-2.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué dice realmente cada etiqueta?","grupos":[{"id":"g1","nombre":"Dice algo concreto"},{"id":"g2","nombre":"Dice poco o confunde"}],"items":[{"id":"i1","texto":"Compostable industrialmente según norma"},{"id":"i2","texto":"Biodegradable, sin más datos"},{"id":"i3","texto":"Contenido reciclado 50 % certificado"},{"id":"i4","texto":"Oxodegradable"},{"id":"i5","texto":"Reciclable donde se recolecta PET"},{"id":"i6","texto":"Degradable"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las etiquetas útiles dicen en qué condiciones y con qué norma."}},{"slug":"consumo-2.s4.p8","orden":8,"grupo":"consumo-2.s4.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Comprás vasos \"compostables\" para un cumpleaños. ¿Qué conviene hacer con ellos después?","opciones":[{"id":"o1","texto":"Averiguar si hay compostaje industrial que los reciba"},{"id":"o2","texto":"Tirarlos en la calle porque se degradan solos"},{"id":"o3","texto":"Ponerlos en los reciclables con el plástico"},{"id":"o4","texto":"Enterrarlos en una maceta del balcón"}]},"solucion":{"clave":["o1"],"explicacion":"Sin el sistema adecuado, un compostable termina como cualquier residuo. Lo mejor, muchas veces, es usar vajilla lavable.","por_opcion":{"o3":"Pueden contaminar el reciclaje de plástico, porque son otro material."}}},{"slug":"consumo-2.s4.p9","orden":9,"grupo":"consumo-2.s4.p9","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas afirmaciones son correctas? Marcá todas.","opciones":[{"id":"o1","texto":"\"Reciclable\" no garantiza que se recicle"},{"id":"o2","texto":"Muchos compostables necesitan compostaje industrial"},{"id":"o3","texto":"Los oxodegradables se convierten en microplásticos"},{"id":"o4","texto":"\"Biodegradable\" sin condiciones dice poco"},{"id":"o5","texto":"\"Degradable\" significa que desaparece sin dejar rastro"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cada palabra tiene letra chica. Leerla es no dejarse engañar."}},{"slug":"consumo-2.s4.p10","orden":10,"grupo":"consumo-2.s4.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para vasos de un evento, de menor a mayor impacto.","items":[{"id":"i1","texto":"Vasos lavables que se reutilizan"},{"id":"i2","texto":"Vasos compostables llevados a compostaje industrial"},{"id":"i3","texto":"Vasos de plástico reciclable separados para reciclar"},{"id":"i4","texto":"Vasos oxodegradables tirados en cualquier lado"}],"extremos":["Menor impacto","Mayor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La jerarquía otra vez: reutilizar le gana a cualquier descartable, por verde que parezca.","valores":{"i1":"menor impacto","i2":"bajo","i3":"medio","i4":"mayor impacto"}}},{"slug":"consumo-2.s4.p11","orden":11,"grupo":"consumo-2.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un envase tiene el símbolo de tres flechas en círculo. ¿Qué garantiza por sí solo?","opciones":[{"id":"o1","texto":"Nada concreto: hay que leer qué dice al lado"},{"id":"o2","texto":"Que el envase se va a reciclar seguro"},{"id":"o3","texto":"Que el envase está hecho 100 % de material reciclado"},{"id":"o4","texto":"Que se puede tirar en cualquier tacho"}]},"solucion":{"clave":["o1"],"explicacion":"El símbolo se usa de muchas formas. La información útil es la que lo acompaña: material, porcentaje, dónde se recicla.","por_opcion":{"o3":"El símbolo solo no dice cuánto material reciclado tiene ni si se reciclará."}}},{"slug":"consumo-2.s4.p12","orden":12,"grupo":"consumo-2.s4.p12","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un envase pesa 20 g y tiene 30 % de contenido reciclado. ¿Cuántos gramos de material reciclado tiene?","unidad":"g","decimales":1},"solucion":{"valor":6,"tolerancia":0.12,"explicacion":"20 × 30 ÷ 100 = 6 g reciclados; los otros 14 g son material nuevo."}},{"slug":"consumo-2.s4.p12.v2","orden":12,"grupo":"consumo-2.s4.p12","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un envase pesa 30 g y tiene 50 % de contenido reciclado. ¿Cuántos gramos de material reciclado tiene?","unidad":"g","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"30 × 50 ÷ 100 = 15 g reciclados; los otros 15 g son material nuevo."}},{"slug":"consumo-2.s4.p12.v3","orden":12,"grupo":"consumo-2.s4.p12","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un envase pesa 50 g y tiene 25 % de contenido reciclado. ¿Cuántos gramos de material reciclado tiene?","unidad":"g","decimales":1},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"50 × 25 ÷ 100 = 12,5 g reciclados; los otros 37,5 g son material nuevo."}},{"slug":"consumo-2.s4.p13","orden":13,"grupo":"consumo-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este envase y marcá lo que confunde o engaña.","segmentos":[{"id":"s1","texto":"Bolsa hecha con 40 % de plástico reciclado."},{"id":"s2","texto":"Oxobiodegradable: desaparece sin dejar rastro."},{"id":"s3","texto":"Reciclable en los puntos verdes que aceptan polietileno."},{"id":"s4","texto":"Biodegradable, ideal para tirar en la naturaleza."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las palabras verdes pueden esconder problemas. La letra chica importa.","por_opcion":{"s2":"Se fragmenta en microplásticos: no desaparece.","s4":"Ningún envase debe tirarse en la naturaleza; y \"biodegradable\" no dice en qué condiciones."}}},{"slug":"consumo-2.s4.p14","orden":14,"grupo":"consumo-2.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un envase {{0}} se podría reciclar; uno {{1}} ya tiene material recuperado; y los plásticos oxodegradables se vuelven {{2}}.","banco":[{"id":"w1","texto":"reciclable"},{"id":"w2","texto":"reciclado"},{"id":"w3","texto":"microplásticos"},{"id":"w4","texto":"compostable"},{"id":"w5","texto":"nuevo"},{"id":"w6","texto":"abono"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres términos que conviene no confundir."}}]},{"slug":"consumo-2.s5","orden":5,"tipo":"leccion","titulo_es":"Leer un producto completo","bajada_es":"Una lista de preguntas para evaluar cualquier producto sin caer en el marketing.","minutos":9,"pasos":[{"slug":"consumo-2.s5.p1","orden":1,"grupo":"consumo-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una lista para la góndola","cuerpo":["Con lo que viste en la rama se puede armar una lista breve para evaluar un producto: ¿lo necesito?, ¿qué dice la información obligatoria?, ¿los sellos son independientes?, ¿las afirmaciones ambientales son concretas y verificables?, ¿dónde está el mayor impacto de este producto?, ¿cuánto va a durar?, ¿qué pasa con el envase y el producto al final?","No hace falta responder todo cada vez. Con la práctica, se vuelve automático."],"lista":["¿Lo necesito?","¿Qué dice lo obligatorio?","¿Los sellos son independientes?","¿Las afirmaciones son verificables?","¿Dónde está el mayor impacto?","¿Cuánto dura?","¿Qué pasa al final?"]},"solucion":{}},{"slug":"consumo-2.s5.p2","orden":2,"grupo":"consumo-2.s5.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las preguntas de la lista en el orden más útil.","items":[{"id":"i1","texto":"¿Lo necesito?"},{"id":"i2","texto":"¿Qué dice la información obligatoria?"},{"id":"i3","texto":"¿Los sellos y afirmaciones son confiables?"},{"id":"i4","texto":"¿Cuánto va a durar?"},{"id":"i5","texto":"¿Qué pasa con el producto y el envase al final?"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Primero la necesidad; después la información real; al final, la vida útil y el destino."}},{"slug":"consumo-2.s5.p3","orden":3,"grupo":"consumo-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Elegir por impacto, también en la góndola","cuerpo":["No todas las decisiones de compra pesan igual. Elegir un detergente con envase de recarga ayuda; elegir qué comemos, qué aparato compramos o si viajamos en avión pesa mucho más. Conviene poner la atención donde el impacto es mayor, como viste en el tronco."]},"solucion":{}},{"slug":"consumo-2.s5.p4","orden":4,"grupo":"consumo-2.s5.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión de compra suele tener un impacto grande o chico?","grupos":[{"id":"g1","nombre":"Grande"},{"id":"g2","nombre":"Chico"}],"items":[{"id":"i1","texto":"Comprar un auto"},{"id":"i2","texto":"Elegir entre dos marcas de birome"},{"id":"i3","texto":"Elegir la heladera"},{"id":"i4","texto":"El color de la bolsa de residuos"},{"id":"i5","texto":"Cuánta carne vacuna comprar por semana"},{"id":"i6","texto":"La marca de fósforos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Revisar con cuidado las decisiones grandes rinde mucho más que obsesionarse con las chicas."}},{"slug":"consumo-2.s5.p5","orden":5,"grupo":"consumo-2.s5.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene revisar antes de comprar un electrodoméstico grande? Marcá todo.","opciones":[{"id":"o1","texto":"La etiqueta de eficiencia energética"},{"id":"o2","texto":"La garantía y los repuestos"},{"id":"o3","texto":"El consumo anual en kWh"},{"id":"o4","texto":"Si hay servicio técnico cerca"},{"id":"o5","texto":"El color de la caja"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"En los aparatos grandes, eficiencia y durabilidad son las claves."}},{"slug":"consumo-2.s5.p6","orden":6,"grupo":"consumo-2.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un detergente concentrado rinde 5 lavados por cada 2 que rinde uno común, con el mismo envase. ¿Cuántas veces menos envases hacen falta con el concentrado? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":2.5,"tolerancia":0.05,"explicacion":"5 ÷ 2 ≈ 2,5 veces menos envases para la misma cantidad de lavados. Concentrar es reducir."}},{"slug":"consumo-2.s5.p6.v2","orden":6,"grupo":"consumo-2.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un detergente concentrado rinde 4 lavados por cada 3 que rinde uno común, con el mismo envase. ¿Cuántas veces menos envases hacen falta con el concentrado? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":1.3,"tolerancia":0.05,"explicacion":"4 ÷ 3 ≈ 1,3 veces menos envases para la misma cantidad de lavados. Concentrar es reducir."}},{"slug":"consumo-2.s5.p6.v3","orden":6,"grupo":"consumo-2.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un detergente concentrado rinde 3 lavados por cada 1 que rinde uno común, con el mismo envase. ¿Cuántas veces menos envases hacen falta con el concentrado? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"3 ÷ 1 ≈ 3 veces menos envases para la misma cantidad de lavados. Concentrar es reducir."}},{"slug":"consumo-2.s5.p7","orden":7,"grupo":"consumo-2.s5.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Dos lavandinas: una en botella común, otra con sello \"eco\" de la marca y el doble de precio. ¿Qué conviene mirar para decidir?","opciones":[{"id":"o1","texto":"Qué certifica el sello y quién lo otorga"},{"id":"o2","texto":"Cuál tiene la botella más linda"},{"id":"o3","texto":"Comprar la más cara, porque es mejor"},{"id":"o4","texto":"Cuál tiene más veces la palabra \"eco\""}]},"solucion":{"clave":["o1"],"explicacion":"Un sello de la propia marca no es una certificación. Antes de pagar el doble, conviene verificar.","por_opcion":{"o3":"El precio no garantiza un menor impacto."}}},{"slug":"consumo-2.s5.p8","orden":8,"grupo":"consumo-2.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un consumidor informado presiona a las empresas.","items":[{"id":"i1","texto":"Más personas leen etiquetas y verifican sellos"},{"id":"i2","texto":"Las frases vagas dejan de convencer"},{"id":"i3","texto":"Las empresas necesitan datos y certificaciones reales"},{"id":"i4","texto":"Mejoran sus productos o su información"},{"id":"i5","texto":"Las empresas dejan de vender productos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La información es una palanca: cambia lo que se exige y lo que se ofrece."}},{"slug":"consumo-2.s5.p9","orden":9,"grupo":"consumo-2.s5.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un producto es más caro y dice \"verde\", seguro tiene menor impacto.","razones":[{"id":"r1","texto":"Porque ni el precio ni la palabra verde garantizan menor impacto"},{"id":"r2","texto":"Porque los productos caros siempre contaminan más"},{"id":"r3","texto":"Porque la palabra verde está prohibida"}]},"solucion":{"valor":false,"explicacion":"El precio y la palabra \"verde\" no garantizan nada. Hay que ver qué afirma, quién lo verifica y dónde está el impacto real.","clave":["r1"]}},{"slug":"consumo-2.s5.p10","orden":10,"grupo":"consumo-2.s5.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta decisión de compra y marcá los errores.","segmentos":[{"id":"s1","texto":"Antes de comprar, me pregunté si lo necesitaba."},{"id":"s2","texto":"Elegí el que tenía una hojita verde, aunque no dice quién lo certifica."},{"id":"s3","texto":"Revisé la etiqueta de eficiencia del lavarropas."},{"id":"s4","texto":"Compré vasos biodegradables para tirarlos en la plaza sin culpa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Aplicar la lista evita los errores más comunes.","por_opcion":{"s2":"Sin organismo ni norma, la hojita es marketing.","s4":"Ningún descartable debe tirarse en el espacio público, y \"biodegradable\" no dice en qué condiciones."}}},{"slug":"consumo-2.s5.p11","orden":11,"grupo":"consumo-2.s5.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de comprar, la primera pregunta es si lo {{0}}; conviene poner más atención en las decisiones de mayor {{1}}.","banco":[{"id":"w1","texto":"necesito"},{"id":"w2","texto":"impacto"},{"id":"w3","texto":"quiero"},{"id":"w4","texto":"precio"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La lista de preguntas, resumida en sus dos ideas clave."}},{"slug":"consumo-2.s5.p12","orden":12,"grupo":"consumo-2.s5.p12","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada producto con la pregunta más importante para evaluarlo.","izquierda":[{"id":"a1","texto":"Heladera"},{"id":"a2","texto":"Remera"},{"id":"a3","texto":"Detergente con sello verde"},{"id":"a4","texto":"Vasos compostables"}],"derecha":[{"id":"b1","texto":"¿Cuánto consume por año?"},{"id":"b2","texto":"¿Cuántas veces la voy a usar?"},{"id":"b3","texto":"¿Quién certifica el sello?"},{"id":"b4","texto":"¿Hay compostaje que los reciba?"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada producto tiene su pregunta clave según dónde está su impacto."}}]},{"slug":"consumo-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: etiquetas, sellos y greenwashing","bajada_es":"Etiquetas, sellos, lavado verde, palabras engañosas y evaluación de productos, mezclados.","minutos":8,"pasos":[{"slug":"consumo-2.s6.p1","orden":1,"grupo":"consumo-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Etiquetas, sellos y greenwashing». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"consumo-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la góndola de limpieza","bajada_es":"Tres productos de limpieza compiten en la góndola con promesas verdes. Analizalos y elegí con fundamento.","minutos":10,"pasos":[{"slug":"consumo-2.s7.p1","orden":1,"grupo":"consumo-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los tres productos","cuerpo":["Producto A: detergente común, botella de 750 ml, sin afirmaciones ambientales, rinde 30 lavados. Producto B: botella de 750 ml con una hoja verde, la frase \"eco-friendly, amigable con el planeta\" y \"envase oxobiodegradable\"; rinde 30 lavados y cuesta el doble. Producto C: detergente concentrado en envase de recarga de 500 ml, con 50 % de plástico reciclado certificado y un sello de una certificadora independiente con norma pública; rinde 60 lavados."]},"solucion":{}},{"slug":"consumo-2.s7.p2","orden":2,"grupo":"consumo-2.s7.p2","tipo":"multiple","di